64	
65	/**
66	 * @author Vitaliy Fedoriv
67	 */
68	
69	@RestController
70	@CrossOrigin(exposedHeaders = "errors, content-type")
71	@RequestMapping("/api")
72	public class OwnerRestControllerV1 implements OwnersApi {
73	
74	    /**
75	     * Dedicated audit logger. On a successful owner create an audit line carrying the owner id,
76	     * the {@code customerCode} and the {@code registrationDate} is emitted to this named logger.
77	     */
78	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
79	
80	    private final ClinicService clinicService;
81	
82	    private final OwnerMapper ownerMapper;
83	
84	    private final PetMapper petMapper;
85	
86	    private final VisitMapper visitMapper;
87	
88	    public OwnerRestControllerV1(ClinicService clinicService,
89	                                 OwnerMapper ownerMapper,
90	                                 PetMapper petMapper,
91	                                 VisitMapper visitMapper) {
92	        this.clinicService = clinicService;
93	        this.ownerMapper = ownerMapper;
94	        this.petMapper = petMapper;
95	        this.visitMapper = visitMapper;
96	    }
97	
98	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
99	    @Override
100	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
101	        Collection<Owner> owners;
102	        if (lastName != null) {
103	            owners = this.clinicService.findOwnerByLastName(lastName);
104	        } else {
105	            owners = this.clinicService.findAllOwners();
106	        }
107	        if (owners.isEmpty()) {
108	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
109	        }
110	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
111	    }
112	
113	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
114	    @Override
115	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
116	        Owner owner = this.clinicService.findOwnerById(ownerId);
117	        if (owner == null) {
118	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
119	        }
120	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
121	    }
122	
123	    /**
124	     * Rejects an owner payload that is missing or blank in any of the required fields
125	     * (firstName, lastName, address, city, telephone). Bean Validation on the request body
126	     * already rejects {@code null} values and empty strings, but treats a whitespace-only
127	     * value as present; this guard closes that gap so a blank in any required field is
128	     * reported. The thrown exception is translated to a 400 whose {@code errors} array lists
129	     * the name of each offending field.
130	     */
131	    private void rejectMissingOrBlankFields(OwnerFieldsDto ownerFieldsDto, String normalizedAddress) {
132	        List<String> missing = new ArrayList<>();
133	        if (isBlank(ownerFieldsDto.getFirstName())) {
134	            missing.add("firstName");
135	        }
136	        if (isBlank(ownerFieldsDto.getLastName())) {
137	            missing.add("lastName");
138	        }
139	        if (isBlank(normalizedAddress)) {
140	            missing.add("address");
141	        }
142	        if (isBlank(ownerFieldsDto.getCity())) {
143	            missing.add("city");
144	        }
145	        if (isBlank(ownerFieldsDto.getTelephone())) {
146	            missing.add("telephone");
147	        }
148	        if (!missing.isEmpty()) {
149	            throw new MissingOwnerFieldsException(missing);
150	        }
151	    }
152	
153	    private static boolean isBlank(String value) {
154	        return value == null || value.isBlank();
155	    }
156	
157	    /**
158	     * Matches a well-formed E.164 telephone: a leading '+' followed by 8 to 15 digits.
159	     */
160	    private static final Pattern E164_PATTERN = Pattern.compile("\\+\\d{8,15}");
161	
162	    /**
163	     * Required national-number length per country calling code. When the normalized E.164 number
164	     * begins with one of these codes, the digits that follow must number exactly the mapped value:
165	     * '+61' (Australia) requires 9 national digits and '+1' (NANP) requires 10. Codes absent from
166	     * this map carry no per-country length rule beyond the generic E.164 8-to-15-digit bound.
167	     */
168	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of(
169	        "+61", 9,
170	        "+1", 10);
171	
172	    /**
173	     * Normalizes an owner's telephone on create into E.164 form. Spaces, dashes and brackets are
174	     * stripped. When a leading '+' (with its country code) is present it is kept as-is; otherwise
175	     * the country code '+61' is assumed and a single leading '0' is dropped from the national
176	     * digits. The result must be a '+' followed by 8 to 15 digits, so e.g. '0412 345 678' is
177	     * stored as '+61412345678'. When the country code has a known national-number length ('+61'
178	     * requires 9 national digits, '+1' requires 10) the national digits must match it exactly. A
179	     * value that cannot form a valid E.164 number, or whose national length is wrong for its
180	     * country, is rejected via {@link InvalidTelephoneException}, which the exception handler
181	     * translates to a 400.
182	     */
183	    private static String normalizeTelephone(String telephone) {
184	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()\\[\\]]", "");
185	        String e164;
186	        if (cleaned.startsWith("+")) {
187	            e164 = cleaned;
188	        } else {
189	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
190	            e164 = "+61" + national;
191	        }
192	        if (!E164_PATTERN.matcher(e164).matches()) {
193	            throw new InvalidTelephoneException(telephone);
194	        }
195	        for (Map.Entry<String, Integer> rule : NATIONAL_NUMBER_LENGTHS.entrySet()) {
196	            String code = rule.getKey();
197	            if (e164.startsWith(code)) {
198	                int nationalLength = e164.length() - code.length();
199	                if (nationalLength != rule.getValue()) {
200	                    throw new InvalidTelephoneException(telephone);
201	                }
202	                break;
203	            }
204	        }
205	        return e164;
206	    }
207	
208	    /**
209	     * A pragmatic syntactic email check: a non-empty local part, an {@code @}, and a domain that
210	     * carries at least one dot, with no whitespace anywhere. Deliberately permissive — it accepts
211	     * ordinary addresses while rejecting obvious non-addresses such as one lacking an {@code @}.
212	     */
213	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
214	
215	    /**
216	     * Normalizes an optional owner email. A {@code null} email is left as-is (the field is
217	     * optional). When present it must be a syntactically valid address; a valid value is
218	     * lower-cased so it is stored and returned in canonical form. An invalid value is rejected via
219	     * {@link InvalidEmailException}, which the exception handler translates to a 400.
220	     */
221	    private static String normalizeEmail(String email) {
222	        if (email == null) {
223	            return null;
224	        }
225	        if (!EMAIL_PATTERN.matcher(email).matches()) {
226	            throw new InvalidEmailException(email);
227	        }
228	        return email.toLowerCase(Locale.ROOT);
229	    }
230	
231	    /**
232	     * The single derived identity of an owner, {@code normalizedTelephone + '|' + (email or empty)
233	     * + '|' + householdId}, into which all duplicate detection is consolidated. Two owners are the
234	     * same identity only when this whole key matches: because the normalized telephone is part of
235	     * the key, two members of the same household (same {@code householdId}) with different
236	     * telephones have different identity keys. A {@code null} email contributes an empty middle
237	     * segment. This is the value returned to callers as {@code identityKey}.
238	     */
239	    private static String identityKeyFor(String normalizedTelephone, String normalizedEmail, String householdId) {
240	        return normalizedTelephone + "|" + (normalizedEmail == null ? "" : normalizedEmail) + "|" + householdId;
241	    }
242	
243	    /**
244	     * Rejects a create whose derived identity collides with an existing owner's, reported via one
245	     * of the {@code Duplicate*} exceptions the handler translates to a 409. The former separate
246	     * telephone, email and household checks are now expressed through the components of the single
247	     * identity key:
248	     * <ul>
249	     *   <li>the normalized telephone matches an existing owner's canonical E.164 telephone (an
250	     *       existing value that cannot form a valid E.164 number is skipped rather than colliding);</li>
251	     *   <li>a present, lower-cased email matches an existing owner's lower-cased email (a {@code null}
252	     *       candidate email, being optional, is not compared, and existing owners without an email
253	     *       are skipped);</li>
254	     *   <li>the {@code householdId} matches an existing owner's - unless the caller opted into sharing
255	     *       a household via {@code sharesHousehold}, in which case the household component is not
256	     *       compared.</li>
257	     * </ul>
258	     */
259	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto, String normalizedTelephone,
260	                                         String normalizedEmail, String householdId) {
261	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
262	        for (Owner existing : this.clinicService.findAllOwners()) {
263	            String existingTelephone;
264	            try {
265	                existingTelephone = normalizeTelephone(existing.getTelephone());
266	            } catch (InvalidTelephoneException ex) {
267	                existingTelephone = null;
268	            }
269	            if (normalizedTelephone.equals(existingTelephone)) {
270	                throw new DuplicateTelephoneException(normalizedTelephone);
271	            }
272	            if (normalizedEmail != null) {
273	                String existingEmail = existing.getEmail();
274	                if (existingEmail != null && normalizedEmail.equals(existingEmail.toLowerCase(Locale.ROOT))) {
275	                    throw new DuplicateEmailException(normalizedEmail);
276	                }
277	            }
278	            if (!sharesHousehold
279	                && householdId.equals(householdIdFor(existing.getLastName(), existing.getAddress()))) {
280	                throw new DuplicateHouseholdException(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
281	            }
282	        }
283	    }
284	
285	    /**
286	     * Collapses a value for household comparison: leading and trailing whitespace is trimmed, any
287	     * internal run of whitespace is reduced to a single space, and the result is lower-cased. This
288	     * is how both {@code lastName} and {@code address} are compared so that differences of case or
289	     * spacing do not defeat the duplicate-household check.
290	     */
291	    private static String collapse(String value) {
292	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
293	    }
294	
295	    /**
296	     * Normalizes an owner's address into a canonical form applied on every create: leading and
297	     * trailing whitespace is trimmed, any internal run of whitespace is reduced to a single space,
298	     * the value is upper-cased, and common street-type abbreviations are expanded on a per-word
299	     * basis ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The result is stored
300	     * and returned, and is the form every address comparison (duplicate-household detection and the
301	     * shared {@code householdId}) uses. A {@code null} or whitespace-only input normalizes to the
302	     * empty string, which the required-field guard then rejects. The transformation is idempotent,
303	     * so normalizing an already-normalized address is a no-op.
304	     */
305	    private static String normalizeAddress(String address) {
306	        if (address == null) {
307	            return "";
308	        }
309	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
310	        if (collapsed.isEmpty()) {
311	            return "";
312	        }
313	        String[] tokens = collapsed.split(" ");
314	        StringBuilder sb = new StringBuilder(collapsed.length());
315	        for (int i = 0; i < tokens.length; i++) {
316	            String token = tokens[i];
317	            switch (token) {
318	                case "ST" -> token = "STREET";
319	                case "RD" -> token = "ROAD";
320	                case "AVE" -> token = "AVENUE";
321	                default -> {
322	                }
323	            }
324	            if (i > 0) {
325	                sb.append(' ');
326	            }
327	            sb.append(token);
328	        }
329	        return sb.toString();
330	    }
331	
332	    /**
333	     * Builds the {@code customerCode} for a newly created owner, formatted
334	     * {@code '<CITY3>-<LAST3>-<NNNN>'} where {@code CITY3} is the upper-cased first three letters of
335	     * {@code city}, {@code LAST3} the upper-cased first three letters of {@code lastName}, and
336	     * {@code NNNN} a per-city 4-digit zero-padded sequence equal to one more than the number of
337	     * owners already in that city (e.g. {@code 'SYD-SMI-0007'}).
338	     */
339	    private String nextCustomerCode(String city, String lastName) {
340	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
341	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
342	        int sequence = 1;
343	        for (Owner existing : this.clinicService.findAllOwners()) {
344	            if (city.equalsIgnoreCase(existing.getCity())) {
345	                sequence++;
346	            }
347	        }
348	        return String.format("%s-%s-%04d", city3, last3, sequence);
349	    }
350	
351	    /**
352	     * Builds the {@code membershipNumber} for a newly created owner, formatted
353	     * {@code '<customerCode>-M<YY>'} where {@code YY} is the last two digits of the
354	     * {@code registrationDate} year (e.g. {@code 'SMI-0007-M26'}).
355	     */
356	    private static String membershipNumberFor(String customerCode, LocalDate registrationDate) {
357	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
358	    }
359	
360	    /**
361	     * Derives the stable {@code householdId} for an owner from the collapsed {@code lastName} and
362	     * {@code address} - the same pair used to detect a shared household. Because it is a pure
363	     * function of that pair (upper-case hex of SHA-256 over the two collapsed values), every owner
364	     * in the same household - whether created first or joining later via {@code sharesHousehold} -
365	     * receives the identical, non-blank identifier without needing to read any other owner's value.
366	     */
367	    private static String householdIdFor(String lastName, String address) {
368	        String key = collapse(lastName) + "\n" + normalizeAddress(address);
369	        try {
370	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
371	            StringBuilder sb = new StringBuilder(32);
372	            for (int i = 0; i < 8; i++) {
373	                sb.append(String.format("%02X", digest[i]));
374	            }
375	            return sb.toString();
376	        } catch (NoSuchAlgorithmException ex) {
377	            throw new IllegalStateException("SHA-256 not available", ex);
378	        }
379	    }
380	
381	    /**
382	     * Counts the existing owners who already share the given {@code firstName} and {@code lastName},
383	     * compared case-insensitively. This is evaluated before the new owner is saved, so it reflects
384	     * the state prior to this create and is stored on the owner as its {@code namesakeCount}.
385	     */
386	    private int countNamesakes(String firstName, String lastName) {
387	        int count = 0;
388	        for (Owner existing : this.clinicService.findAllOwners()) {
389	            if (firstName.equalsIgnoreCase(existing.getFirstName())
390	                && lastName.equalsIgnoreCase(existing.getLastName())) {
391	                count++;
392	            }
393	        }
394	        return count;
395	    }
396	
397	    /**
398	     * Counts the members of the household the new owner will belong to, as it stands after this
399	     * create. Every existing owner carrying the same {@code householdId} is counted, and the new
400	     * owner itself is added, so a value of 3 or more means the owner joins a household of at least
401	     * three members. This is evaluated with the new owner's {@code householdId} already set and is
402	     * stored on the owner as its {@code householdMemberCount}.
403	     */
404	    private int countHouseholdMembers(String householdId) {
405	        int count = 1;
406	        for (Owner existing : this.clinicService.findAllOwners()) {
407	            if (householdId.equals(existing.getHouseholdId())) {
408	                count++;
409	            }
410	        }
411	        return count;
412	    }
413	
414	    /**
415	     * The membership level ceiling assigned on create; level 4 is reserved for tenure and so is
416	     * never reached here.
417	     */
418	    private static final int MAX_MEMBERSHIP_LEVEL = 3;
419	
420	    /**
421	     * Computes the numeric {@code membershipLevel} for a newly created owner. It starts at 1,
422	     * gains 1 when an email is present, gains 1 when the owner's {@code namesakeCount} is 0, and
423	     * is capped at {@value #MAX_MEMBERSHIP_LEVEL} (level 4 is reserved for tenure). Evaluated after
424	     * the owner's email and namesakeCount have been set.
425	     */
426	    private static int membershipLevelFor(Owner owner) {
427	        int level = 1;
428	        if (owner.getEmail() != null && !owner.getEmail().isEmpty()) {
429	            level++;
430	        }
431	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
432	            level++;
433	        }
434	        return Math.min(level, MAX_MEMBERSHIP_LEVEL);
435	    }
436	
437	    /**
438	     * The maximum number of owners any single city may contain. A create whose city already
439	     * holds this many owners is rejected.
440	     */
441	    private static final int CITY_CAPACITY = 50;
442	
443	    /**
444	     * Rejects a create whose city already contains {@value #CITY_CAPACITY} or more owners,
445	     * compared case-insensitively - the same way the city is matched when building the
446	     * {@code customerCode} sequence. The count reflects the state prior to this create. A city
447	     * at capacity is reported via {@link CityAtCapacityException}, which the exception handler
448	     * translates to a 409.
449	     */
450	    private void rejectCityAtCapacity(String city) {
451	        int count = 0;
452	        for (Owner existing : this.clinicService.findAllOwners()) {
453	            if (city.equalsIgnoreCase(existing.getCity())) {
454	                count++;
455	            }
456	        }
457	        if (count >= CITY_CAPACITY) {
458	            throw new CityAtCapacityException(city);
459	        }
460	    }
461	
462	    /**
463	     * The maximum number of owners that may be created on any single day (by
464	     * {@code registrationDate}). A create attempted once this many owners already carry the
465	     * current day's registration date is rejected.
466	     */
467	    private static final int DAILY_OWNER_LIMIT = 100;
468	
469	    /**
470	     * Rejects a create once {@value #DAILY_OWNER_LIMIT} or more owners already carry the given
471	     * business-day-adjusted {@code registrationDate} (the date the new owner will itself receive).
472	     * The count reflects the state prior to this create. When the limit is reached the create is
473	     * reported via {@link DailyOwnerLimitExceededException}, which the exception handler translates
474	     * to a 429 Too Many Requests.
475	     */
476	    private void rejectDailyOwnerLimit(LocalDate registrationDate) {
477	        int count = 0;
478	        for (Owner existing : this.clinicService.findAllOwners()) {
479	            if (registrationDate.equals(existing.getRegistrationDate())) {
480	                count++;
481	            }
482	        }
483	        if (count >= DAILY_OWNER_LIMIT) {
484	            throw new DailyOwnerLimitExceededException();
485	        }
486	    }
487	
488	    /**
489	     * The number of owners that must already carry a given {@code registrationDate} before a
490	     * create on that date is flagged with a bulk-signup warning. Once <em>more than</em> this
491	     * many owners already exist for the day, the new owner's {@code bulkSignupWarning} is true.
492	     */
493	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
494	
495	    /**
496	     * Computes the {@code bulkSignupWarning} for a create on the given business-day-adjusted
497	     * {@code registrationDate}: true when more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners
498	     * have already been created for that date, otherwise false. The count reflects the state prior
499	     * to this create, matching how the daily-limit rule accumulates.
500	     */
501	    private boolean bulkSignupWarningFor(LocalDate registrationDate) {
502	        int count = 0;
503	        for (Owner existing : this.clinicService.findAllOwners()) {
504	            if (registrationDate.equals(existing.getRegistrationDate())) {
505	                count++;
506	            }
507	        }
508	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
509	    }
510	
511	    /**
512	     * Rolls an effective registration date forward onto a business day. A Saturday or Sunday is
513	     * advanced to the following Monday; a weekday is returned unchanged. This is applied to the
514	     * effective registration date - whether supplied in the request or defaulted to the server
515	     * date - so the stored {@code registrationDate}, and everything derived from it, always falls
516	     * on a business day.
517	     */
518	    private static LocalDate toBusinessDay(LocalDate date) {
519	        return switch (date.getDayOfWeek()) {
520	            case SATURDAY -> date.plusDays(2);
521	            case SUNDAY -> date.plusDays(1);
522	            default -> date;
523	        };
524	    }
525	
526	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
527	    @Override
528	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
529	        String normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
530	        rejectMissingOrBlankFields(ownerFieldsDto, normalizedAddress);
531	        rejectCityAtCapacity(ownerFieldsDto.getCity());
532	        HttpHeaders headers = new HttpHeaders();
533	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
534	        owner.setAddress(normalizedAddress);
535	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
536	        owner.setTelephone(normalizedTelephone);
537	        String normalizedEmail = normalizeEmail(ownerFieldsDto.getEmail());
538	        owner.setEmail(normalizedEmail);
539	        String householdId = householdIdFor(owner.getLastName(), owner.getAddress());
540	        rejectDuplicateIdentity(ownerFieldsDto, normalizedTelephone, normalizedEmail, householdId);
541	        LocalDate effectiveDate = owner.getRegistrationDate() == null ? LocalDate.now() : owner.getRegistrationDate();
542	        LocalDate registrationDate = toBusinessDay(effectiveDate);
543	        rejectDailyOwnerLimit(registrationDate);
544	        owner.setBulkSignupWarning(bulkSignupWarningFor(registrationDate));
545	        owner.setRegistrationDate(registrationDate);
546	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
547	        owner.setMembershipNumber(membershipNumberFor(owner.getCustomerCode(), owner.getRegistrationDate()));
548	        owner.setHouseholdId(householdId);
549	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
550	        owner.setHouseholdMemberCount(countHouseholdMembers(owner.getHouseholdId()));
551	        owner.setMembershipLevel(membershipLevelFor(owner));
552	        this.clinicService.saveOwner(owner);
553	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
554	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel());
555	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
556	        headers.setLocation(UriComponentsBuilder.newInstance()
557	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
558	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
559	    }
560	
561	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
562	    @Override
563	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
564	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
565	        if (currentOwner == null) {
566	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
567	        }
568	        currentOwner.setAddress(ownerFieldsDto.getAddress());
569	        currentOwner.setCity(ownerFieldsDto.getCity());
570	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
571	        currentOwner.setLastName(ownerFieldsDto.getLastName());
572	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
573	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
574	        this.clinicService.saveOwner(currentOwner);
575	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
576	    }
577	
578	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
579	    @Transactional
580	    @Override
581	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
582	        Owner owner = this.clinicService.findOwnerById(ownerId);
583	        if (owner == null) {
584	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
585	        }
586	        this.clinicService.deleteOwner(owner);
587	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
588	    }
589	
590	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
591	    @Override
592	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
593	        Owner owner = this.clinicService.findOwnerById(ownerId);
594	        if (owner == null) {
595	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
596	        }
597	        HttpHeaders headers = new HttpHeaders();
598	        Pet pet = petMapper.toPet(petFieldsDto);
599	        owner.setId(ownerId);
600	        pet.setOwner(owner);
601	        pet.getType().setName(null);
602	        this.clinicService.savePet(pet);
603	        PetDto petDto = petMapper.toPetDto(pet);
604	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
605	            .buildAndExpand(pet.getId()).toUri());
606	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
607	    }
608	
609	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
610	    @Override
611	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
612	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
613	        if (currentOwner != null) {
614	            Pet currentPet = this.clinicService.findPetById(petId);
615	            if (currentPet != null) {
616	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
617	                currentPet.setName(petFieldsDto.getName());
618	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
619	                this.clinicService.savePet(currentPet);
620	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
621	            }
622	        }
623	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
624	    }
625	
626	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
627	    @Override
628	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
629	        HttpHeaders headers = new HttpHeaders();
630	        Visit visit = visitMapper.toVisit(visitFieldsDto);
631	        Pet pet = new Pet();
632	        pet.setId(petId);
633	        visit.setPet(pet);
634	        this.clinicService.saveVisit(visit);
635	        VisitDto visitDto = visitMapper.toVisitDto(visit);
636	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
637	            .buildAndExpand(visit.getId()).toUri());
638	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
639	    }
640	
641	
642	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
643	    @Override
644	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
645	        Owner owner = this.clinicService.findOwnerById(ownerId);
646	        if (owner != null) {
647	            Pet pet = owner.getPet(petId);
648	            if (pet != null) {
649	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
650	            }
651	        }
652	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
653	    }
654	}
